-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (6703, 3, 'Netzentgelte mit Bundesmitteln senken oder deckeln', 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'belegt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Zuschuss für 2026 beträgt 6,5 Mrd. Euro und wird aus dem Klima- und Transformationsfonds bezahlt.","quelle_url":"https://dserver.bundestag.de/btd/21/027/2102754.pdf","belegstufe":"A"}]'::jsonb),
  (6704, 3, 'Stromsteuer für alle auf das EU-Mindestmaß senken', 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'belegt', null, 'bund', null, true, null, '[]'::jsonb),
  (6705, 3, 'Klimageld: Einnahmen aus dem CO₂-Preis pro Kopf an die Haushalte zurückgeben', 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'belegt', null, 'bund', null, true, null, '[{"bereich":"verteilung","richtung":"vorteil","text":"Eine gleiche Pauschale je Person entlastet Haushalte mit geringem Einkommen im Durchschnitt; mittlere Einkommen bleiben etwa gleich, die oberen 30 % zahlen leicht drauf.","quelle_url":"https://www.diw.de/de/diw_01.c.917856.de/publikationen/wochenberichte/2024_42_1/.html","belegstufe":"B"}]'::jsonb),
  (6706, 3, 'CO₂-Preis auf Heizen abschaffen', 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'belegt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der nationale CO₂-Preis auf Heizen und Verkehr brachte 2024 rund 13 Mrd. Euro für den Klima- und Transformationsfonds; der Anteil aus dem Heizen fiele weg.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/einnahmen-aus-dem-emissionshandel-erneut-auf","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ein CO₂-Preis senkt nach Simulationen den Verbrauch von Heizöl und Gas und damit die Emissionen; dieser Anreiz entfiele beim Heizen.","quelle_url":"https://www.diw.de/de/diw_01.c.635240.de/themen_nachrichten/diw_berlin_analysiert_klima_und_verteilungswirkungen_eines_co2_preises_im_waerme_und_verkehrssektor.html","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Der CO₂-Preis belastet Haushalte mit geringem Einkommen anteilig stärker (Simulation 2020: 0,8 % gegenüber 0,25 % des Nettoeinkommens); diese Last entfiele.","quelle_url":"https://www.diw.de/de/diw_01.c.635240.de/themen_nachrichten/diw_berlin_analysiert_klima_und_verteilungswirkungen_eines_co2_preises_im_waerme_und_verkehrssektor.html","belegstufe":"B"}]'::jsonb),
  (6707, 3, 'Erneuerbare Energien und Speicher schneller ausbauen', 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"umwelt","richtung":"vorteil","text":"Erneuerbare Energien vermieden 2025 rund 265 Mio. t Treibhausgase; mehr Wind- und Solarstrom senkt den Ausstoß weiter.","quelle_url":"https://www.umweltbundesamt.de/daten/energie/erneuerbare-energien-vermiedene-treibhausgase","belegstufe":"A"},{"bereich":"haushalt","richtung":"nachteil","text":"Die Förderung nach dem EEG wird aus dem Bundeshaushalt bezahlt; laut Bundesregierung entspricht das derzeit rund 5 Cent je Kilowattstunde.","quelle_url":"https://dserver.bundestag.de/btd/21/014/2101408.pdf","belegstufe":"A"}]'::jsonb),
  (6708, 3, 'Kohle- und Kernkraftwerke länger oder wieder betreiben', 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Kohlekraftwerke stoßen mehr Treibhausgase aus als andere Kraftwerke; ein längerer Betrieb erhöht die Emissionen.","quelle_url":"https://www.umweltbundesamt.de/presse/pressedossiers/pressedossier-braun-steinkohle","belegstufe":"A"}]'::jsonb),
  (6709, 3, 'Dynamische Stromtarife und intelligente Messsysteme', 'Haushalte, die Strom in günstigen Stunden nutzen können, sparen; für viele Haushalte ohne Wärmepumpe, E-Auto oder Batterie ist die Ersparnis gering.', 'gemischt', null, 'bund', null, true, null, '[]'::jsonb),
  (6828, 3, 'Wieder Gas aus Russland über Nord Stream beziehen', 'Mehr Pipelinegas könnte den Gaspreis senken, würde die Abhängigkeit von einem einzelnen Lieferland aber wieder erhöhen; die EU hat mit der Verordnung (EU) 2026/261 die Einfuhr von russischem Gas verboten (Pipelinegas spätestens ab Herbst 2027), eine Wiederaufnahme wäre EU-rechtswidrig.', 'gemischt', null, 'bund', null, true, null, '[]'::jsonb)
