  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft,
  nebenwirkungen = excluded.nebenwirkungen;

delete from public.instrumente where thema_id = 3 and id not in (6703, 6704, 6705, 6706, 6707, 6708, 6709, 6828);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (6710, 3, 11, null, 'Netzentgelte senken und neu regeln', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Zuschuss für 2026 beträgt 6,5 Mrd. Euro und wird aus dem Klima- und Transformationsfonds bezahlt.","quelle_url":"https://dserver.bundestag.de/btd/21/027/2102754.pdf","belegstufe":"A"}]'::jsonb),
  (6711, 3, 11, null, 'Stromsteuer für alle senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'belegt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6712, 3, 11, null, 'Klimabonus als sozialer Ausgleich für den CO₂-Preis', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"verteilung","richtung":"vorteil","text":"Eine gleiche Pauschale je Person entlastet Haushalte mit geringem Einkommen im Durchschnitt; mittlere Einkommen bleiben etwa gleich, die oberen 30 % zahlen leicht drauf.","quelle_url":"https://www.diw.de/de/diw_01.c.917856.de/publikationen/wochenberichte/2024_42_1/.html","belegstufe":"B"}]'::jsonb),
  (6713, 3, 11, null, 'Prüfen, ob die zuletzt abgeschalteten Kernkraftwerke wieder in Betrieb gehen können', '{304}', 6708, 1, 1, null, 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Kohlekraftwerke stoßen mehr Treibhausgase aus als andere Kraftwerke; ein längerer Betrieb erhöht die Emissionen.","quelle_url":"https://www.umweltbundesamt.de/presse/pressedossiers/pressedossier-braun-steinkohle","belegstufe":"A"}]'::jsonb),
  (6714, 3, 11, null, 'Smart Meter und Digitalisierung, damit Verbraucher flexibler auf den Strompreis reagieren können', '{304}', 6709, 1, 3, null, 'Haushalte, die Strom in günstigen Stunden nutzen können, sparen; für viele Haushalte ohne Wärmepumpe, E-Auto oder Batterie ist die Ersparnis gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6715, 3, 11, null, 'Investitionen in Energieeffizienz steuerlich schneller absetzbar', '{305}', null, 1, 2, null, 'Macht Sanierungen und Heizungstausch für Eigentümer günstiger und senkt langfristig den Verbrauch; Mieterinnen und Mieter profitieren nur indirekt, und der Steuervorteil hilft Haushalten mit hohem Einkommen mehr.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6716, 3, 12, null, 'Übertragungsnetzentgelte stabilisieren und auf 3 Cent pro Kilowattstunde deckeln', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Zuschuss für 2026 beträgt 6,5 Mrd. Euro und wird aus dem Klima- und Transformationsfonds bezahlt.","quelle_url":"https://dserver.bundestag.de/btd/21/027/2102754.pdf","belegstufe":"A"}]'::jsonb),
  (6717, 3, 12, null, 'Klimageld, wenn ab 2027 der europäische CO₂-Preis gilt', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"verteilung","richtung":"vorteil","text":"Eine gleiche Pauschale je Person entlastet Haushalte mit geringem Einkommen im Durchschnitt; mittlere Einkommen bleiben etwa gleich, die oberen 30 % zahlen leicht drauf.","quelle_url":"https://www.diw.de/de/diw_01.c.917856.de/publikationen/wochenberichte/2024_42_1/.html","belegstufe":"B"}]'::jsonb),
  (6718, 3, 12, null, 'Wind- und Solarenergie konsequent ausbauen, Speicher einbinden', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"vorteil","text":"Erneuerbare Energien vermieden 2025 rund 265 Mio. t Treibhausgase; mehr Wind- und Solarstrom senkt den Ausstoß weiter.","quelle_url":"https://www.umweltbundesamt.de/daten/energie/erneuerbare-energien-vermiedene-treibhausgase","belegstufe":"A"},{"bereich":"haushalt","richtung":"nachteil","text":"Die Förderung nach dem EEG wird aus dem Bundeshaushalt bezahlt; laut Bundesregierung entspricht das derzeit rund 5 Cent je Kilowattstunde.","quelle_url":"https://dserver.bundestag.de/btd/21/014/2101408.pdf","belegstufe":"A"}]'::jsonb),
  (6719, 3, 12, null, 'Soziales Wärmepumpen-Leasing für ärmere Haushalte', '{305}', null, 1, 2, null, 'Senkt die Hürde, von Gas oder Öl auf eine Wärmepumpe umzusteigen, für Haushalte ohne Ersparnisse; die meisten ärmeren Haushalte wohnen zur Miete und entscheiden nicht über die Heizung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'offen', '2026-09-30', false, true, null, '[]'::jsonb),
  (6720, 3, 13, null, 'Netzentgelte für überregionale Stromleitungen aus dem Deutschlandfonds bezahlen', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=17', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Zuschuss für 2026 beträgt 6,5 Mrd. Euro und wird aus dem Klima- und Transformationsfonds bezahlt.","quelle_url":"https://dserver.bundestag.de/btd/21/027/2102754.pdf","belegstufe":"A"}]'::jsonb),
  (6721, 3, 13, null, 'Stromsteuer auf das europäische Minimum senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=17', null, 'belegt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6722, 3, 13, null, 'Sozial gestaffeltes Klimageld', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"verteilung","richtung":"vorteil","text":"Eine gleiche Pauschale je Person entlastet Haushalte mit geringem Einkommen im Durchschnitt; mittlere Einkommen bleiben etwa gleich, die oberen 30 % zahlen leicht drauf.","quelle_url":"https://www.diw.de/de/diw_01.c.917856.de/publikationen/wochenberichte/2024_42_1/.html","belegstufe":"B"}]'::jsonb),
  (6723, 3, 13, null, 'Dynamische Stromtarife und flexible Netze', '{304}', 6709, 1, 3, null, 'Haushalte, die Strom in günstigen Stunden nutzen können, sparen; für viele Haushalte ohne Wärmepumpe, E-Auto oder Batterie ist die Ersparnis gering.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6724, 3, 13, null, 'Strom in spätestens zehn Jahren vollständig erneuerbar', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"vorteil","text":"Erneuerbare Energien vermieden 2025 rund 265 Mio. t Treibhausgase; mehr Wind- und Solarstrom senkt den Ausstoß weiter.","quelle_url":"https://www.umweltbundesamt.de/daten/energie/erneuerbare-energien-vermiedene-treibhausgase","belegstufe":"A"},{"bereich":"haushalt","richtung":"nachteil","text":"Die Förderung nach dem EEG wird aus dem Bundeshaushalt bezahlt; laut Bundesregierung entspricht das derzeit rund 5 Cent je Kilowattstunde.","quelle_url":"https://dserver.bundestag.de/btd/21/014/2101408.pdf","belegstufe":"A"}]'::jsonb),
  (6725, 3, 13, null, 'Förderung von bis zu 70 Prozent für fossilfreie Heizungen', '{305}', null, 2, 3, null, 'Macht den Umstieg von Gas und Öl auf Wärmepumpen und Wärmenetze bezahlbarer und koppelt die Heizkosten von fossilen Preisen ab; die Förderung besteht bereits, der Umstieg dauert aber Jahre und hängt vom Strompreis ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Bundesförderung für effiziente Gebäude ist im Regierungsentwurf zum Haushalt 2027 mit rund 12,56 Mrd. Euro im KTF veranschlagt – das Programm insgesamt, nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"},{"bereich":"umwelt","richtung":"gemischt","text":"Wärmepumpen vermieden laut Umweltbundesamt 2020 rund 2 Mio. t Treibhausgase bei 1,3 Mio. Anlagen; entweichendes Kältemittel verursacht zusätzliche Emissionen.","quelle_url":"https://www.umweltbundesamt.de/themen/klima-energie/erneuerbare-energien/umgebungswaerme-waermepumpen","belegstufe":"A"}]'::jsonb),
  (6726, 3, 14, null, 'Stromsteuer auf das EU-Mindestmaß senken, langfristig abschaffen', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'belegt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6727, 3, 14, null, 'Netzausbau günstiger: Freileitungen statt Erdkabel, dynamische Netzentgelte', '{301}', null, 2, 2, null, 'Freileitungen sind deutlich billiger als Erdkabel und dämpfen so den Anstieg der Netzentgelte; für viele bereits geplante Leitungen wäre ein Wechsel aufwendig, und Freileitungen stoßen vor Ort häufiger auf Widerstand.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Freileitungen führen laut Bundesamt für Naturschutz zu Kollisionen von Vögeln, Eingriffen in Gehölzbestände und Beeinträchtigungen des Landschaftsbildes.","quelle_url":"https://www.bfn.de/stromleitungen","belegstufe":"A"}]'::jsonb),
  (6728, 3, 14, null, 'Klimadividende: Einnahmen aus dem Emissionshandel pro Kopf zurückzahlen', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"verteilung","richtung":"vorteil","text":"Eine gleiche Pauschale je Person entlastet Haushalte mit geringem Einkommen im Durchschnitt; mittlere Einkommen bleiben etwa gleich, die oberen 30 % zahlen leicht drauf.","quelle_url":"https://www.diw.de/de/diw_01.c.917856.de/publikationen/wochenberichte/2024_42_1/.html","belegstufe":"B"}]'::jsonb),
  (6729, 3, 15, null, 'CO₂-Abgabe abschaffen', '{302,305}', 6706, 2, 1, null, 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der nationale CO₂-Preis auf Heizen und Verkehr brachte 2024 rund 13 Mrd. Euro für den Klima- und Transformationsfonds; der Anteil aus dem Heizen fiele weg.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/einnahmen-aus-dem-emissionshandel-erneut-auf","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ein CO₂-Preis senkt nach Simulationen den Verbrauch von Heizöl und Gas und damit die Emissionen; dieser Anreiz entfiele beim Heizen.","quelle_url":"https://www.diw.de/de/diw_01.c.635240.de/themen_nachrichten/diw_berlin_analysiert_klima_und_verteilungswirkungen_eines_co2_preises_im_waerme_und_verkehrssektor.html","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Der CO₂-Preis belastet Haushalte mit geringem Einkommen anteilig stärker (Simulation 2020: 0,8 % gegenüber 0,25 % des Nettoeinkommens); diese Last entfiele.","quelle_url":"https://www.diw.de/de/diw_01.c.635240.de/themen_nachrichten/diw_berlin_analysiert_klima_und_verteilungswirkungen_eines_co2_preises_im_waerme_und_verkehrssektor.html","belegstufe":"B"}]'::jsonb),
  (6730, 3, 15, null, 'Energiesteuer reduzieren, Stromsteuer auf das Minimum senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'belegt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6731, 3, 15, null, 'Kohlekraftwerke länger betreiben, Wiedereinstieg in die Kernenergie', '{304}', 6708, 1, 1, null, 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Kohlekraftwerke stoßen mehr Treibhausgase aus als andere Kraftwerke; ein längerer Betrieb erhöht die Emissionen.","quelle_url":"https://www.umweltbundesamt.de/presse/pressedossiers/pressedossier-braun-steinkohle","belegstufe":"A"}]'::jsonb),
  (6732, 3, 15, null, 'Nord-Stream-Pipelines reparieren und wieder in Betrieb nehmen', '{303}', 6828, 1, 0, null, 'Mehr Pipelinegas könnte den Gaspreis senken, würde die Abhängigkeit von einem einzelnen Lieferland aber wieder erhöhen; die EU hat mit der Verordnung (EU) 2026/261 die Einfuhr von russischem Gas verboten (Pipelinegas spätestens ab Herbst 2027), eine Wiederaufnahme wäre EU-rechtswidrig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6733, 3, 15, null, 'Ausbau der Windenergie stoppen, um höhere Netzentgelte zu verhindern', '{301}', null, 1, 3, null, 'Weniger neue Windparks bedeuten weniger neuen Netzausbau; zugleich fehlt günstiger Windstrom, sodass teurere Kraftwerke den Börsenpreis öfter bestimmen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Windenergie ist laut Umweltbundesamt der wichtigste Träger bei der Vermeidung von Treibhausgasen; ein Ausbaustopp verzichtet auf weitere Einsparungen.","quelle_url":"https://www.umweltbundesamt.de/daten/energie/erneuerbare-energien-vermiedene-treibhausgase","belegstufe":"A"}]'::jsonb),
  (6734, 3, 16, null, 'Soziales Klimageld von 320 Euro pro Person und Jahr', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=7', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"verteilung","richtung":"vorteil","text":"Eine gleiche Pauschale je Person entlastet Haushalte mit geringem Einkommen im Durchschnitt; mittlere Einkommen bleiben etwa gleich, die oberen 30 % zahlen leicht drauf.","quelle_url":"https://www.diw.de/de/diw_01.c.917856.de/publikationen/wochenberichte/2024_42_1/.html","belegstufe":"B"}]'::jsonb),
  (6735, 3, 16, null, 'Neue Netzentgeltstruktur: Stromerzeuger und Stromhandel an den Transportkosten beteiligen', '{301}', null, 1, 1, null, 'Würde Haushalte bei den Netzentgelten entlasten; Entgelte für Erzeuger begrenzt das EU-Recht eng, und die Kosten würden zum Teil über höhere Strompreise wieder bei den Verbrauchern landen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'offen', '2026-09-30', false, true, null, '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Erzeugungsanlagen sollen künftig voraussichtlich 4 bis 7 Euro je kW und Jahr zahlen; Bestandsanlagen sind 20 Jahre ausgenommen, der Marktpreis ändert sich laut Bundesnetzagentur kaum.","quelle_url":"https://www.bundesnetzagentur.de/SharedDocs/Pressemitteilungen/DE/2026/20260527_Agnes.html","belegstufe":"A"}]'::jsonb),
  (6736, 3, 16, null, 'Stromsteuer auf den europäischen Mindeststeuersatz senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'belegt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6737, 3, 16, null, 'Schnellstmöglich auf erneuerbare Energien umsteigen', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"vorteil","text":"Erneuerbare Energien vermieden 2025 rund 265 Mio. t Treibhausgase; mehr Wind- und Solarstrom senkt den Ausstoß weiter.","quelle_url":"https://www.umweltbundesamt.de/daten/energie/erneuerbare-energien-vermiedene-treibhausgase","belegstufe":"A"},{"bereich":"haushalt","richtung":"nachteil","text":"Die Förderung nach dem EEG wird aus dem Bundeshaushalt bezahlt; laut Bundesregierung entspricht das derzeit rund 5 Cent je Kilowattstunde.","quelle_url":"https://dserver.bundestag.de/btd/21/014/2101408.pdf","belegstufe":"A"}]'::jsonb),
  (6738, 3, 16, null, 'Keine CO₂-Preise im Wärmebereich', '{302,305}', 6706, 2, 1, null, 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der nationale CO₂-Preis auf Heizen und Verkehr brachte 2024 rund 13 Mrd. Euro für den Klima- und Transformationsfonds; der Anteil aus dem Heizen fiele weg.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/einnahmen-aus-dem-emissionshandel-erneut-auf","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ein CO₂-Preis senkt nach Simulationen den Verbrauch von Heizöl und Gas und damit die Emissionen; dieser Anreiz entfiele beim Heizen.","quelle_url":"https://www.diw.de/de/diw_01.c.635240.de/themen_nachrichten/diw_berlin_analysiert_klima_und_verteilungswirkungen_eines_co2_preises_im_waerme_und_verkehrssektor.html","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Der CO₂-Preis belastet Haushalte mit geringem Einkommen anteilig stärker (Simulation 2020: 0,8 % gegenüber 0,25 % des Nettoeinkommens); diese Last entfiele.","quelle_url":"https://www.diw.de/de/diw_01.c.635240.de/themen_nachrichten/diw_berlin_analysiert_klima_und_verteilungswirkungen_eines_co2_preises_im_waerme_und_verkehrssektor.html","belegstufe":"B"}]'::jsonb),
  (6739, 3, 16, null, 'Heizungstausch nach Einkommen gestaffelt fördern, bis zu 100 Prozent', '{305}', null, 2, 2, null, 'Ermöglicht auch Eigentümern mit wenig Geld den Umstieg von Gas und Öl und koppelt die Heizkosten von fossilen Preisen ab; das Programm soll 25 Milliarden Euro im Jahr kosten, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Das bestehende Gebäudeförderprogramm (BEG) ist im Haushaltsentwurf 2027 mit rund 12,56 Mrd. Euro im KTF angesetzt – das Programm insgesamt, nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Öl- und Gasheizungen verursachen in Privathaushalten laut Umweltbundesamt die meisten CO₂-Emissionen; ein Umstieg etwa auf Wärmepumpen setzt dort an.","quelle_url":"https://www.umweltbundesamt.de/service/newsletter/archiv/uba-aktuell-nr-12026","belegstufe":"A"}]'::jsonb),
  (6820, 3, 14, null, 'Wiederinbetriebnahme der vorhandenen Kernkraftwerke rechtlich ermöglichen', '{304}', 6708, 1, 1, null, 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Kohlekraftwerke stoßen mehr Treibhausgase aus als andere Kraftwerke; ein längerer Betrieb erhöht die Emissionen.","quelle_url":"https://www.umweltbundesamt.de/presse/pressedossiers/pressedossier-braun-steinkohle","belegstufe":"A"}]'::jsonb),
  (6821, 3, 14, null, 'Heimische Erdgasförderung ausbauen, auch mit Fracking', '{303}', null, 1, 2, null, 'Mehr heimisches Gas verringert die Importe etwas; der Gaspreis bildet sich aber auf dem europäischen Markt, und die möglichen Mengen sind im Vergleich zum Verbrauch klein. Genehmigungen, vor allem für Fracking, dauern lange.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Fracking kann laut Umweltbundesamt das Grundwasser verunreinigen, vor allem durch eingesetzte Chemikalien und das zurückfließende Lagerstättenwasser.","quelle_url":"https://www.umweltbundesamt.de/node/3427","belegstufe":"B"}]'::jsonb),
  (6822, 3, 11, null, 'Europäischen Energiebinnenmarkt stärken, internationale Energiepartnerschaften ausbauen', '{303}', null, 1, 3, null, 'Mehr Lieferländer machen Deutschland weniger anfällig für Preissprünge bei einzelnen Lieferanten; die Maßnahme bleibt allgemein und nennt keine konkreten Schritte.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'offen', '2026-09-30', false, true, null, '[]'::jsonb),
  (6823, 3, 13, null, 'Gasverbrauch schneller senken, Umstieg auf erneuerbare Energien', '{303}', null, 1, 2, null, 'Weniger Gasverbrauch verringert die Importabhängigkeit und damit das Risiko von Preissprüngen; die Wirkung auf die Rechnungen der Haushalte stellt sich erst über Jahre ein.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Erneuerbare Energien vermieden 2024 laut Umweltbundesamt bereits rund 259 Mio. t CO₂-Äquivalente, davon 40 Mio. t im Wärmesektor.","quelle_url":"https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024","belegstufe":"A"}]'::jsonb),
  (6829, 3, 17, null, 'Netze aus öffentlichen Mitteln statt über den Strompreis finanzieren', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der Zuschuss für 2026 beträgt 6,5 Mrd. Euro und wird aus dem Klima- und Transformationsfonds bezahlt.","quelle_url":"https://dserver.bundestag.de/btd/21/027/2102754.pdf","belegstufe":"A"}]'::jsonb),
  (6830, 3, 17, null, 'Stromnetze verstaatlichen und Netzentgelte auf ein Minimum senken', '{301}', null, 1, 1, null, 'Ohne Renditen für private Netzbetreiber könnten die Netzentgelte etwas sinken; der Kauf der Netze würde viele Milliarden kosten, und der Ausbau bliebe trotzdem zu bezahlen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'offen', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich auf Landesebene: Berlin erwartete 2021 für den Kauf seines Stromnetzes Anschaffungskosten von rund 2,14 Mrd. Euro, finanziert über Kredite mit Landesbürgschaften.","quelle_url":"https://www.berlin.de/rbmskzl/aktuelles/pressemitteilungen/2021/pressemitteilung.1079401.php","belegstufe":"A"}]'::jsonb),
  (6831, 3, 17, null, 'CO₂-Preis abschaffen', '{302,305}', 6706, 2, 1, null, 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der nationale CO₂-Preis auf Heizen und Verkehr brachte 2024 rund 13 Mrd. Euro für den Klima- und Transformationsfonds; der Anteil aus dem Heizen fiele weg.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/einnahmen-aus-dem-emissionshandel-erneut-auf","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Ein CO₂-Preis senkt nach Simulationen den Verbrauch von Heizöl und Gas und damit die Emissionen; dieser Anreiz entfiele beim Heizen.","quelle_url":"https://www.diw.de/de/diw_01.c.635240.de/themen_nachrichten/diw_berlin_analysiert_klima_und_verteilungswirkungen_eines_co2_preises_im_waerme_und_verkehrssektor.html","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Der CO₂-Preis belastet Haushalte mit geringem Einkommen anteilig stärker (Simulation 2020: 0,8 % gegenüber 0,25 % des Nettoeinkommens); diese Last entfiele.","quelle_url":"https://www.diw.de/de/diw_01.c.635240.de/themen_nachrichten/diw_berlin_analysiert_klima_und_verteilungswirkungen_eines_co2_preises_im_waerme_und_verkehrssektor.html","belegstufe":"B"}]'::jsonb),
  (6832, 3, 17, null, 'Mit Russland über Gaslieferungen durch Nord Stream verhandeln', '{303}', 6828, 1, 0, null, 'Mehr Pipelinegas könnte den Gaspreis senken, würde die Abhängigkeit von einem einzelnen Lieferland aber wieder erhöhen; die EU hat mit der Verordnung (EU) 2026/261 die Einfuhr von russischem Gas verboten (Pipelinegas spätestens ab Herbst 2027), eine Wiederaufnahme wäre EU-rechtswidrig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6833, 3, 17, null, 'Langfristige Lieferverträge für Energieimporte nach dem niedrigsten Preis', '{303}', null, 1, 2, null, 'Langfristige Verträge können Preisschwankungen dämpfen; sie binden aber auch an Preise, wenn der Markt fällt, und ein Kriterium nur nach dem Preis erhöht die Abhängigkeit von einzelnen Lieferländern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null, '[]'::jsonb),
  (6834, 3, 17, null, 'Neue Gaskraftwerke als Reserve für Dunkelflauten', '{304}', null, 1, 2, null, 'Mehr Reservekraftwerke können Preisspitzen in wind- und sonnenarmen Stunden dämpfen; sie senken den Durchschnittspreis kaum, weil gerade Gaskraftwerke den Preis dann setzen, und müssen über Umlagen oder Steuern bezahlt werden.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Die neuen Gaskraftwerke (zunächst rund 11 GW) sollen wasserstofffähig sein und erst ab 2045 klimaneutral betrieben werden; bis dahin ist ein Betrieb mit Erdgas möglich.","quelle_url":"https://www.bundestag.de/dokumente/textarchiv/2026/kw28-de-versorgungssicherheit-strom-1192538","belegstufe":"A"}]'::jsonb),
  (6835, 3, 17, null, 'Repowering: alte Windanlagen durch neue ersetzen', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"umwelt","richtung":"vorteil","text":"Erneuerbare Energien vermieden 2025 rund 265 Mio. t Treibhausgase; mehr Wind- und Solarstrom senkt den Ausstoß weiter.","quelle_url":"https://www.umweltbundesamt.de/daten/energie/erneuerbare-energien-vermiedene-treibhausgase","belegstufe":"A"},{"bereich":"haushalt","richtung":"nachteil","text":"Die Förderung nach dem EEG wird aus dem Bundeshaushalt bezahlt; laut Bundesregierung entspricht das derzeit rund 5 Cent je Kilowattstunde.","quelle_url":"https://dserver.bundestag.de/btd/21/014/2101408.pdf","belegstufe":"A"}]'::jsonb),
  (6836, 3, 17, null, 'Einbau von Wärmepumpen fördern, ohne andere Heizungen zu benachteiligen', '{305}', null, 1, 3, null, 'Förderung erleichtert den Umstieg von Gas und Öl; ohne Vorgaben für neue Heizungen bleiben viele Haushalte bei fossilen Heizungen und damit von deren Preisen abhängig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Im Regierungsentwurf des Bundeshaushalts 2027 sind rund 12,56 Mrd. Euro im Klima- und Transformationsfonds für die Bundesförderung für effiziente Gebäude vorgesehen, die auch Heizungstausch umfasst.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1205500","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Wärmepumpen ersetzen fossile Heizungen; laut Umweltbundesamt ist ihre Klimabilanz schon heute gut und wird mit mehr Strom aus erneuerbaren Energien besser, Ölheizungen emittieren am meisten CO₂.","quelle_url":"https://www.umweltbundesamt.de/themen/mehr-klimaschutz-einer-neuen-heizung","belegstufe":"A"}]'::jsonb);

